const W=20,H=12;
const mapRows=[
'gggggggggggggggggggg',
'ggttggggggggggttgggg',
'ggttggggggggggttgggg',
'ggggggggppgggggggggg',
'ggggggggppgggggggggg',
'ggggwwwwwwwwwwgggggg',
'ggggwwwwwwwwwwgggggg',
'ggggwwwwwwwwwwgggggg',
'ggggggggppgggggggggg',
'ggggggggppgggggggggg',
'ggggggbbppgggggggggg',
'ggggggbbppgggggggggg'
];
const map=mapRows.map(r=>r.split(''));
// Points of interest are embedded as special props on otherwise walkable tiles.
const props={ '7,3':{type:'sign',emoji:'🪧'},'8,10':{type:'guild',emoji:'🏠'},'7,10':{type:'guild',emoji:'🏠'},'9,9':{type:'alchemy',emoji:'⚗️'},'3,5':{type:'reed',emoji:'🌾'},'16,4':{type:'bush',emoji:'🫐'},'14,9':{type:'rock',emoji:'🪨'},'4,9':{type:'flower',emoji:'🌼'},'12,2':{type:'tree',emoji:'🌳'}};
const terrainEmoji={t:'🌲',r:'🪨',b:'🏠'};
const state={x:8,y:8, catches:0,fishQuest:0,rep:12,coins:120,inventory:{'Torgand-Saft':2,'Karpfen-Schuppenhaut':0,'Mondminze':0,'Batterie':0,'Filter':0,'UV-Spektral-Modul':0,'Karpfen-Essenz':0,'Schatzkarten-Fragment':0,'Wanderfisch':0,'Silberkarpfen':0},enchantments:[],logs:[],minute:42,moonlight:false,recipe:null,revealed:0,seed:Math.random().toString(36).slice(2,7),listings:[{name:'Mondminze',qty:2,price:18,emoji:'🌿'},{name:'Schatzkarten-Fragment',qty:1,price:42,emoji:'🗺️'},{name:'Karpfen-Schuppenhaut',qty:1,price:35,emoji:'🐟'}]};
const el=id=>document.getElementById(id);const itemEmoji={'Torgand-Saft':'🧪','Karpfen-Schuppenhaut':'🐟','Mondminze':'🌿','Batterie':'🔋','Filter':'◈','UV-Spektral-Modul':'☼','Karpfen-Essenz':'✨','Schatzkarten-Fragment':'🗺️','Wanderfisch':'🐠','Silberkarpfen':'🐟','Treibholz':'🪵','Schattenpilz':'🍄'};
function terrain(x,y){return map[y]?.[x]||'g'}function isWater(x,y){return terrain(x,y)==='w'}
function drawMap(){const world=el('world');world.innerHTML='';for(let y=0;y<H;y++)for(let x=0;x<W;x++){let t=terrain(x,y),tile=document.createElement('div');tile.className='tile '+({g:'grass',w:'water',p:'path',t:'tree',b:'building'}[t]||'grass');tile.dataset.x=x;tile.dataset.y=y;let prop=props[`${x},${y}`];if(prop){tile.classList.add('tile-shadow');tile.innerHTML=`<span>${prop.emoji}</span>`}else if(terrainEmoji[t])tile.innerHTML=`<span>${terrainEmoji[t]}</span>`;if(x===state.x&&y===state.y){tile.classList.add('player');tile.innerHTML='<div class="player-token">🧢</div>'}world.append(tile)}el('coords').textContent=`X ${String(state.x).padStart(2,'0')} · Y ${String(state.y).padStart(2,'0')}`;updatePlace()}
function updatePlace(){const nearWater=[[-1,0],[1,0],[0,-1],[0,1]].some(([dx,dy])=>isWater(state.x+dx,state.y+dy));el('placeName').textContent=nearWater?'Silberufer':(props[`${state.x},${state.y}`]?.type==='guild'?'Gildensteg':'Mondhain');el('placeDesc').textContent=nearWater?'Ein stiller See, voller Geheimnisse.':props[`${state.x},${state.y}`]?.type==='guild'?'Händler, Forschung und Geschichten.':'Wildkräuter wachsen zwischen den alten Pfaden.'}
function log(text,special=false){let d=new Date();let time=`${String((8+Math.floor(state.minute/60))%24).padStart(2,'0')}:${String(state.minute%60).padStart(2,'0')}`;state.logs.unshift({text,time,special});state.logs=state.logs.slice(0,6);el('logList').innerHTML=state.logs.map(x=>`<div class="log-line ${x.special?'special':''}"><span class="log-time">${x.time}</span><span>${x.text}</span></div>`).join('')}
let toastTimer;function toast(text){const node=el('toast');node.textContent=text;node.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>node.classList.remove('show'),2300)}
function addItem(name,n=1){state.inventory[name]=(state.inventory[name]||0)+n;renderInventory()}function consume(name,n=1){if((state.inventory[name]||0)<n)return false;state.inventory[name]-=n;renderInventory();return true}
function renderInventory(){const grid=el('inventoryGrid'),items=Object.entries(state.inventory).filter(([,n])=>n>0);grid.innerHTML=items.length?items.slice(0,6).map(([name,n])=>`<div class="item-slot"><span class="item-emoji">${itemEmoji[name]||'✦'}</span><span class="item-info"><b>${name}</b><small>Rucksack</small></span><span class="item-count">×${n}</span></div>`).join(''):`<div class="empty-slots">Dein Rucksack ist noch leer.</div>`;el('coinsTop').textContent=state.coins;el('catchCount').textContent=state.catches;el('rodProgress').style.width=`${state.catches%100}%`;el('nextCatch').textContent=`${state.catches%100} · 100`;el('questCount').textContent=`${Math.min(state.fishQuest,3)}/3`;el('questBar').style.width=`${Math.min(100,state.fishQuest/3*100)}%`;el('repValue').textContent=`${state.rep} / 100`;el('repBar').style.width=`${state.rep}%`;}
function tick(n=7){state.minute=(state.minute+n)%720;}
function nearby(type){return Object.entries(props).find(([key,p])=>p.type===type&&Math.abs(+key.split(',')[0]-state.x)+Math.abs(+key.split(',')[1]-state.y)<=1)}
function step(dx,dy){let nx=state.x+dx,ny=state.y+dy;if(nx<0||ny<0||nx>=W||ny>=H||terrain(nx,ny)==='w'||terrain(nx,ny)==='t'||terrain(nx,ny)==='b'){toast('Dort kommst du nicht entlang.');return}state.x=nx;state.y=ny;tick(2);drawMap();if(props[`${nx},${ny}`]?.type==='sign')toast('Wegweiser: Gilde im Süden, Angelplatz im Westen.');renderInventory()}
function fisher(){let near=[[-1,0],[1,0],[0,-1],[0,1]].some(([dx,dy])=>isWater(state.x+dx,state.y+dy));if(!near){toast('Geh bis ans Wasser, bevor du die Angel auswirfst.');return}tick(12);state.catches++;state.fishQuest++;state.rep=Math.min(100,state.rep+2);let roll=Math.random(),fish=roll<.13?'Silberkarpfen':'Wanderfisch';addItem(fish);let msg=`Du fängst ${fish==='Silberkarpfen'?'einen <strong>Silberkarpfen</strong>':'einen <strong>Wanderfisch</strong>'}.`;if(fish==='Silberkarpfen'){addItem('Karpfen-Schuppenhaut');msg+=' Die Schuppenhaut glimmt im Zwielicht.'}if(Math.random()<.23){addItem('Schatzkarten-Fragment');state.revealed=Math.min(3,state.revealed+1);msg+=' Ein <strong>Schatzkarten-Fragment</strong> verfängt sich im Netz!';updateHint()}if(state.fishQuest===3){state.coins+=45;state.rep=Math.min(100,state.rep+12);msg+=' <strong>Auftrag erfüllt!</strong> +45 Taler.'}if(state.catches%100===0){const prefixes=['Quanten','Void','Solar','Echo','Prismen','Quanten-Resonanz','Nebel','Sternen'];const suffixes=['des Hais','der Tiefsee','der Unendlichkeit','des Masterminds','des Mondfischs','der Gezeiten'];const enchant=`${prefixes[Math.floor(Math.random()*prefixes.length)]}-Haken ${suffixes[Math.floor(Math.random()*suffixes.length)]} · Stufe ${Math.floor(Math.random()*999)+1}`;state.enchantments.push(enchant);msg+=` <strong>Meilenstein! Neue Verzauberung: ${enchant}</strong>`;log(`Angel-Meilenstein! <strong>${enchant}</strong>`,true)}log(msg,state.catches%100===0);renderInventory();toast(state.catches%100===0?'Meilenstein! Eine neue Verzauberung ist entstanden.':fish==='Silberkarpfen'?'Seltener Fang! Silberkarpfen-Schuppenhaut erhalten.':'Fang gemacht — der nächste könnte ein Schatz sein.')}
function gather(){tick(6);let p=Object.entries(props).find(([key,v])=>Math.abs(+key.split(',')[0]-state.x)+Math.abs(+key.split(',')[1]-state.y)<=1&&['reed','bush','rock','flower','tree'].includes(v.type));let item;if(p){item=p[1].type==='rock'?'Batterie':p[1].type==='bush'?'Torgand-Saft':p[1].type==='tree'?'Filter':'Mondminze';props[p[0]].type='empty';props[p[0]].emoji='';}else item=['Mondminze','Torgand-Saft','Batterie'][Math.floor(Math.random()*3)];addItem(item);state.rep=Math.min(100,state.rep+1);log(`Gesammelt: <strong>${item}</strong>.`);toast(`${itemEmoji[item]} ${item} eingesammelt.`);drawMap()}
function updateHint(){const hints=['„Wo Mondlicht künstlich scheint, erwacht die Essenz.“','„Drei Tropfen Torgand nähren, was Schuppen tragen.“','„Suche nach schimmernder Haut aus dem Silbersee.“'];el('hintBox').innerHTML=`<strong>Fragment ${Math.min(state.revealed,3)}:</strong> „${hints[Math.min(state.revealed-1,2)]}“`;}

