function updateHint(){const hints=['„Wo Mondlicht künstlich scheint, erwacht die Essenz.“','„Drei Tropfen Torgand nähren, was Schuppen tragen.“','„Suche nach schimmernder Haut aus dem Silbersee.“'];el('hintBox').innerHTML=`<strong>Fragment ${Math.min(state.revealed,3)}:</strong> „${hints[Math.min(state.revealed-1,2)]}“`;}
function showModal(title,body,actions=[]){el('modalTitle').textContent=title;el('modalBody').innerHTML=body;el('modalActions').innerHTML='';actions.forEach(a=>{let b=document.createElement('button');b.className=a.secondary?'secondary':'primary';b.textContent=a.label;b.onclick=()=>a.run?.();el('modalActions').append(b)});el('modalBackdrop').classList.add('open')}
function closeModal(){el('modalBackdrop').classList.remove('open')}
function hasNearWater(){return [[-1,0],[1,0],[0,-1],[0,1]].some(([dx,dy])=>isWater(state.x+dx,state.y+dy))}
function craftModule(){if(state.inventory['UV-Spektral-Modul']){toast('Das UV-Modul ist bereits gebaut.');return}if(!consume('Batterie')||!consume('Filter')){toast('Benötigt: 1 Batterie + 1 Filter. Sammle an Felsen und Bäumen.');return}addItem('UV-Spektral-Modul');log('Werkbank: <strong>UV-Spektral-Modul</strong> zusammengebaut.');toast('☼ UV-Spektral-Modul gebaut!')}
function brew(){if(!nearby('alchemy')){toast('Zum Brauen musst du direkt am Alchemie-Regal stehen.');return}tick(8);const req=state.recipe;if(!req){state.recipe={herb:Math.random()<.5?'Torgand-Saft':'Mondminze',count:3,fish:'Karpfen-Schuppenhaut'};}const recipe=state.recipe;if(!state.moonlight){showModal('Das Rezept schweigt',`<p>Am Alchemie-Regal riecht es nach Torgand, aber die Mischung bleibt trüb. Ein künstliches Mondlicht könnte die Essenz wecken.</p><div class="recipe-card"><strong>Fundstücke</strong><div class="secret">Die Hinweise ergeben sich aus Fragmenten — sammle sie beim Angeln.</div></div>`,[{label:'UV-Modul bauen',run:()=>{closeModal();craftModule()}},{label:'Schließen',secondary:true,run:closeModal}]);return}if((state.inventory['Karpfen-Schuppenhaut']||0)<1||(state.inventory[recipe.herb]||0)<recipe.count){showModal('Zutaten fehlen',`<p>Das künstliche Mondlicht ist aktiv. Für die Essenz fehlen noch Zutaten.</p><div class="recipe-card"><strong>Entschlüsselte Spur</strong><div class="secret">1× Karpfen-Schuppenhaut · ${recipe.count}× ${recipe.herb}</div></div>`,[{label:'Schließen',secondary:true,run:closeModal}]);return}consume('Karpfen-Schuppenhaut');consume(recipe.herb,recipe.count);addItem('Karpfen-Essenz');state.rep=Math.min(100,state.rep+8);log('Gebräu gelungen: <strong>Quanten-Karpfen-Essenz</strong> — Schatzchance erhöht.',true);toast('✨ Quanten-Karpfen-Essenz gebraut!');showModal('Essenz gelungen',`<p>Die silbrige Essenz fängt das künstliche Mondlicht ein. Dein nächster Fang hat eine deutlich erhöhte Chance auf seltene Beute.</p><div class="recipe-card"><strong>Quanten-Karpfen-Essenz</strong><div class="secret">Schatzchance +35% für die nächsten 3 Würfe</div></div>`,[{label:'Wunderbar',run:closeModal}]);state.bonusCatches=3}
function activateMoonlight(){if(!state.inventory['UV-Spektral-Modul']){toast('Dir fehlt ein UV-Spektral-Modul.');return}if(!state.moonlight){state.moonlight=true;log('Das <strong>künstliche Mondlicht</strong> erhellt den Alchemietisch.');toast('☾ Künstliches Mondlicht aktiviert.');}else toast('Das künstliche Mondlicht ist bereits aktiv.');}
function inspect(){let prop=props[`${state.x},${state.y}`];let text;if(hasNearWater())text='Das Silberufer kräuselt sich. Hier kannst du angeln. Ab und zu trägt die Strömung Fragmente aus alten Zeiten heran.';else if(prop?.type==='alchemy'||nearby('alchemy'))text='Ein altes Alchemie-Regal. Hier lassen sich Fragmente entschlüsseln und Essenzen brauen.';else if(prop?.type==='guild')text='Der Gildensteg ist das Herz des Handels. Hier treffen Sammler und Forschende aufeinander.';else text='Zwischen Gras und Stein liegen nützliche Dinge verborgen. Sammeln lohnt sich — manche Ressourcen wachsen nur an bestimmten Orten.';showModal('Umgebung untersuchen',`<p>${text}</p><div class="recipe-card"><strong>Weltzeit · ${String(8+Math.floor(state.minute/60)).padStart(2,'0')}:${String(state.minute%60).padStart(2,'0')}</strong><div class="secret">${state.moonlight?'Künstliches Mondlicht aktiv':'Dämmerlicht · tragbares UV-Modul kann Licht jederzeit erzeugen'}</div></div>`,[{label:'Alles klar',run:closeModal}])}
function inventoryModal(){const entries=Object.entries(state.inventory).filter(([,n])=>n>0);const inv=entries.length?entries.map(([name,n])=>`<div class="listing"><span>${itemEmoji[name]||'✦'} <strong>${name}</strong><small>Im Rucksack</small></span><b>×${n}</b></div>`).join(''):'<p>Der Rucksack ist leer.</p>';let enchant=state.enchantments.length?`<div class="recipe-card"><strong>Unendliche Verzauberungen</strong>${state.enchantments.map(x=>`<div class="secret">✧ ${x}</div>`).join('')}</div>`:'<p class="hint">Bei jedem 100. Fang erhält deine Angel eine einmalige prozedurale Verzauberung.</p>';showModal('Rucksack & Ausrüstung',inv+enchant,[{label:'Schließen',run:closeModal}])}
function market(){const listings=state.listings.map((it,i)=>`<div class="listing"><span>${it.emoji} <strong>${it.name}</strong><small>${it.qty} Stück · Gildenbörse</small></span><span><b>${it.price} T</b> <button class="buy" data-buy="${i}">Kaufen</button></span></div>`).join('');showModal('Gildenbörse · /ah',`<p>Ein kleiner, lokaler Markt. Angebote rotieren — kaufe Materialien oder verkaufe deinen Fang.</p>${listings}<div class="hint">Dein Kontostand: <strong>${state.coins} Taler</strong> · Ein Community-Marktplatz wäre online global geteilt.</div>`,[{label:'Schließen',secondary:true,run:closeModal}]);el('modalBody').querySelectorAll('[data-buy]').forEach(btn=>btn.onclick=()=>{let it=state.listings[+btn.dataset.buy];if(state.coins<it.price){toast('Nicht genug Taler.');return}state.coins-=it.price;addItem(it.name,it.qty);state.listings.splice(+btn.dataset.buy,1);renderInventory();log(`Gekauft: <strong>${it.qty}× ${it.name}</strong> für ${it.price} Taler.`);closeModal();market()})}
function sell(){let candidates=Object.entries(state.inventory).filter(([name,n])=>n>0&&!['UV-Spektral-Modul'].includes(name));if(!candidates.length){toast('Nichts zum Verkaufen im Rucksack.');return}const [name,n]=candidates.sort((a,b)=>price(b[0])-price(a[0]))[0];let worth=price(name);consume(name);state.coins+=worth;renderInventory();log(`Verkauft: <strong>${name}</strong> für ${worth} Taler.`);toast(`+${worth} Taler · ${name} verkauft.`)}
function price(name){return({'Schatzkarten-Fragment':42,'Karpfen-Schuppenhaut':35,'Silberkarpfen':24,'Karpfen-Essenz':70,'Wanderfisch':8,'Torgand-Saft':9,'Mondminze':7,'Batterie':16,'Filter':14}[name]||5)}
function interact(){if(hasNearWater())fisher();else if(nearby('alchemy'))brew();else if(nearby('guild'))market();else gather()}

