function gather(){tick(6);const p=Object.entries(props).find(([key,v])=>Math.abs(+key.split(',')[0]-state.x)+Math.abs(+key.split(',')[1]-state.y)<=1&&['reed','bush','rock','flower','tree'].includes(v.type));let item;if(p){item=p[1].type==='rock'?'Batterie':p[1].type==='bush'?'Torgand-Saft':p[1].type==='tree'?'Filter':'Mondminze';props[p[0]].type='empty';props[p[0]].emoji=''}else item=['Mondminze','Torgand-Saft','Batterie','Filter'][Math.floor(Math.random()*4)];addItem(item);state.rep=Math.min(100,state.rep+1);log(`Gesammelt: <strong>${item}</strong>.`);toast(`${itemEmoji[item]||'✦'} ${item} eingesammelt.`);drawMap()}
function showModal(title,body,actions=[]){el('modalTitle').textContent=title;el('modalBody').innerHTML=body;el('modalActions').innerHTML='';for(const action of actions){const button=document.createElement('button');button.textContent=action.label;button.className=action.secondary?'secondary':'';button.onclick=action.run;el('modalActions').append(button)}el('modalBackdrop').style.display='grid'}function closeModal(){el('modalBackdrop').style.display='none'}
function inventoryModal(){const rows=Object.entries(state.inventory).filter(([,n])=>n>0);const list=rows.length?rows.map(([name,n])=>`<div class="item-slot"><span class="item-emoji">${itemEmoji[name]||'✦'}</span><span class="item-info"><b>${name}</b><small>Im Rucksack</small></span><span class="item-count">×${n}</span></div>`).join(''):'<p>Dein Rucksack ist leer.</p>';const ench=state.enchantments.length?`<h3>Verzauberungen</h3><p>${state.enchantments.map(x=>`✧ ${x}`).join('<br>')}</p>`:'<p>Noch keine Angel-Verzauberung. Jeder 100. Fang bringt eine neue.</p>';showModal('Rucksack',`<div class="inventory-grid">${list}</div><div class="divider"></div>${ench}`,[{label:'Schließen',run:closeModal}])}
function marketModal(selling=false){if(selling){const goods=Object.entries(state.inventory).filter(([n,q])=>q>0&&!['Batterie','Filter'].includes(n));const body=goods.length?goods.map(([name,q])=>`<div class="market-entry"><span>${itemEmoji[name]||'✦'} <b>${name}</b> · ×${q}</span><button data-sell="${name}">Verkaufen · ${Math.max(4,Math.round((name==='Silberkarpfen'?24:name==='Karpfen-Schuppenhaut'?16:name==='Schatzkarten-Fragment'?22:8)*.8))} T</button></div>`).join(''):'<p>Zum Verkaufen hast du gerade nichts dabei.</p>';showModal('Waren anbieten',`<p>Verkaufe Gegenstände an die lokale Gildenbörse.</p>${body}`,[{label:'Fertig',run:closeModal}]);el('modalBody').querySelectorAll('[data-sell]').forEach(button=>button.onclick=()=>{const name=button.dataset.sell;if(!consume(name))return;const price=Math.max(4,Math.round((name==='Silberkarpfen'?24:name==='Karpfen-Schuppenhaut'?16:name==='Schatzkarten-Fragment'?22:8)*.8));state.coins+=price;state.rep=Math.min(100,state.rep+1);log(`Verkauft: <strong>${name}</strong> für ${price} Taler.`);renderInventory();marketModal(true)});return}
const rows=state.listings.map((item,i)=>`<div class="market-entry"><span>${item.emoji} <b>${item.name}</b> · ×${item.qty}</span><button data-buy="${i}">Kaufen · ${item.price} T</button></div>`).join('');showModal('Gildenbörse',`<p>Ein kleiner lokaler Markt. Angebote wechseln mit jedem neuen Spielstand.</p>${rows}<div class="divider"></div><p><b>${state.coins} Taler</b> · Dein Guthaben</p>`,[{label:'Verkaufen',run:()=>marketModal(true)},{label:'Schließen',secondary:true,run:closeModal}]);el('modalBody').querySelectorAll('[data-buy]').forEach(button=>button.onclick=()=>{const item=state.listings[Number(button.dataset.buy)];if(state.coins<item.price){toast('Dafür reichen deine Taler nicht.');return}if(!item.qty){toast('Das Angebot ist ausverkauft.');return}state.coins-=item.price;item.qty--;addItem(item.name);log(`Gekauft: <strong>${item.name}</strong> für ${item.price} Taler.`);renderInventory();marketModal(false)})}
function brewMenu(){if(!nearby('alchemy')){toast('Zum Brauen brauchst du das Alchemie-Regal am Gildenpfad.');return}const recipe=state.recipe||{herb:Math.random()<.5?'Torgand-Saft':'Mondminze',count:3+Math.floor(Math.random()*3)};state.recipe=recipe;const has=(n,q=1)=>(state.inventory[n]||0)>=q;const body=`<p>Das alte Regal verbindet Feldfunde mit den Geheimnissen des Sees.</p><div class="market-entry"><span>🔋 Batterie + ◈ Filter<br><small>UV-Spektral-Modul bauen</small></span><button id="craftUv" ${has('Batterie')&&has('Filter')?'':'disabled'}>Bauen</button></div><div class="market-entry"><span>☼ UV-Spektral-Modul<br><small>${state.moonlight?'Mondlicht aktiv':'Benötigt Batterie + Filter'}</small></span><button id="activateUv" ${has('UV-Spektral-Modul')?'':'disabled'}>${state.moonlight?'Deaktivieren':'Aktivieren'}</button></div><div class="market-entry"><span>✨ Karpfen-Essenz<br><small>${recipe.count} × ${recipe.herb} + Schuppenhaut + aktives Mondlicht</small></span><button id="brewEssence" ${has(recipe.herb,recipe.count)&&has('Karpfen-Schuppenhaut')&&state.moonlight?'':'disabled'}>Brauen</button></div><p class="hint">Forschung: „${recipe.count} Tropfen ${recipe.herb} nähren, was Schuppen tragen.“</p>`;showModal('Alchemie-Regal',body,[{label:'Schließen',run:closeModal}]);el('craftUv').onclick=()=>{if(!consume('Batterie')||!consume('Filter'))return;addItem('UV-Spektral-Modul');log('Ein <strong>UV-Spektral-Modul</strong> zusammengebaut.');brewMenu()};el('activateUv').onclick=()=>{if(!state.moonlight){if(!consume('UV-Spektral-Modul'))return;state.moonlight=true;log('Das UV-Modul wirft künstliches <strong>Mondlicht</strong> auf den Alchemietisch.')}else{state.moonlight=false;addItem('UV-Spektral-Modul');log('Das UV-Modul wurde ausgeschaltet und eingepackt.')}brewMenu()};el('brewEssence').onclick=()=>{if(!consume(recipe.herb,recipe.count)||!consume('Karpfen-Schuppenhaut'))return;state.moonlight=false;addItem('Karpfen-Essenz');state.rep=Math.min(100,state.rep+8);log('Unter UV-Mondlicht entsteht <strong>Karpfen-Essenz</strong>!');toast('Karpfen-Essenz gebraut!');brewMenu()}}
function inspect(){const entries=Object.entries(props).filter(([key])=>Math.abs(+key.split(',')[0]-state.x)+Math.abs(+key.split(',')[1]-state.y)<=1);const types=entries.map(([,p])=>p.type);if(types.includes('alchemy'))return brewMenu();if(types.includes('guild'))return showModal('Gildensteg',`<p>Die Gilde handelt mit seltenen Funden und führt deine Forschung.</p><p><b>${state.coins}</b> Taler · Gildenruf <b>${state.rep}/100</b></p>`,[{label:'Börse öffnen',run:()=>marketModal(false)},{label:'Auftrag',run:()=>{if(state.fishQuest>=3){toast(state.questClaimed?'Der Auftrag ist bereits abgeschlossen.':'Auftrag erledigt!')}else toast(`Fange noch ${3-state.fishQuest} Fische am Silberufer.`);closeModal()}},{label:'Schließen',secondary:true,run:closeModal}]);if(types.includes('sign'))return showModal('Wegweiser',`<p><b>Silberufer:</b> westlich der Wiese am großen See. Stelle dich ans Ufer und angle.</p><p><b>Gildensteg:</b> folge dem Steinpfad nach Süden. Beim Alchemie-Regal kannst du Module und Essenz herstellen.</p><p><b>Steuerung:</b> WASD/Pfeiltasten bewegen · E interagieren · Leertaste Aktion.</p>`,[{label:'Verstanden',run:closeModal}]);const spot=nearWater()?'Am Ufer kannst du angeln. Vielleicht wartet zwischen den Fängen ein seltener Silberkarpfen.':'Gras raschelt im Wind. Sammle Kräuter und Materialien in der Nähe.';showModal('Umgebung',`<p>${spot}</p><p>${state.moonlight?'Das UV-Modul leuchtet im Mondlichtmodus.':''}</p>`,[{label:nearWater()?'Angel auswerfen':'Sammeln',run:()=>{closeModal();nearWater()?fisher():gather()}},{label:'Schließen',secondary:true,run:closeModal}])}
function interact(){if(nearby('alchemy'))return brewMenu();if(nearby('guild'))return inspect();if(nearby('sign'))return inspect();if(nearWater())return fisher();gather()}
function help(){showModal('Willkommen in Mondhain',`<p>Erkunde die Wiese, sammle Ressourcen und angle am Silberufer. Fange drei Fische für den Gildenauftrag.</p><p>Beim Alchemie-Regal am südlichen Pfad: <b>Batterie + Filter → UV-Modul</b>, dann einschalten. Sammle Schuppenhaut und die Zutaten deiner Forschungsnotiz, um im künstlichen Mondlicht Karpfen-Essenz zu brauen.</p><p>Der Marktplatz ist eine lokale Simulation; dein Fortschritt wird automatisch in diesem Browser gespeichert.</p><p><b>WASD / Pfeiltasten</b> bewegen · <b>E</b> interagieren · <b>Leertaste</b> Aktion</p>`,[{label:'Los geht’s',run:closeModal}])}
function save(){try{localStorage.setItem('mondhain-save-v1',JSON.stringify(state))}catch(e){}}
function load(){try{const saved=JSON.parse(localStorage.getItem('mondhain-save-v1')||'null');if(saved){Object.assign(state,saved);state.inventory=Object.assign({},state.inventory,saved.inventory||{});state.props=saved.props||null;if(state.props)Object.assign(props,state.props)}}catch(e){}}
function bind(){el('fishBtn').onclick=fisher;el('gatherBtn').onclick=gather;el('brewBtn').onclick=brewMenu;el('inspectBtn').onclick=inspect;el('marketBtn').onclick=()=>marketModal(false);el('sellBtn').onclick=()=>marketModal(true);el('inventoryBtn').onclick=inventoryModal;el('helpBtn').onclick=help;el('modalClose').onclick=closeModal;el('modalBackdrop').addEventListener('click',e=>{if(e.target===el('modalBackdrop'))closeModal()});document.querySelectorAll('[data-dir]').forEach(button=>button.onclick=()=>{const dirs={up:[0,-1],down:[0,1],left:[-1,0],right:[1,0]};step(...dirs[button.dataset.dir])});el('mobileInteract').onclick=interact;document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();return}if(el('modalBackdrop').style.display==='grid')return;const k=e.key.toLowerCase(),dirs={arrowup:[0,-1],w:[0,-1],arrowdown:[0,1],s:[0,1],arrowleft:[-1,0],a:[-1,0],arrowright:[1,0],d:[1,0]};if(dirs[k]){e.preventDefault();step(...dirs[k])}else if(k==='e'){e.preventDefault();interact()}else if(k===' '){e.preventDefault();nearWater()?fisher():gather()}})}
load();bind();drawMap();renderInventory();updateHint();if(!state.logs.length)log('Willkommen in Mondhain. Die Gilde wartet auf deine ersten Fänge.');else{el('logList').innerHTML=state.logs.map(x=>`<div class="log-line ${x.special?'special':''}"><span class="log-time">${x.time}</span><span>${x.text}</span></div>`).join('')}setInterval(save,3000);window.addEventListener('beforeunload',save);
</script></body></html>

