<script>
const W=20,H=12;
const mapRows=['gggggggggggggggggggg','ggttggggggggggttgggg','ggttggggggggggttgggg','ggggggggppgggggggggg','ggggggggppgggggggggg','ggggwwwwwwwwwwgggggg','ggggwwwwwwwwwwgggggg','ggggwwwwwwwwwwgggggg','ggggggggppgggggggggg','ggggggggppgggggggggg','ggggggbbppgggggggggg','ggggggbbppgggggggggg'];
const map=mapRows.map(r=>r.split(''));
const props={'7,3':{type:'sign',emoji:'🪧'},'8,10':{type:'guild',emoji:'🏠'},'7,10':{type:'guild',emoji:'🏠'},'9,9':{type:'alchemy',emoji:'⚗️'},'3,5':{type:'reed',emoji:'🌾'},'16,4':{type:'bush',emoji:'🫐'},'14,9':{type:'rock',emoji:'🪨'},'4,9':{type:'flower',emoji:'🌼'},'12,2':{type:'tree',emoji:'🌳'}};
const state={x:8,y:8,catches:0,fishQuest:0,questClaimed:false,rep:12,coins:120,inventory:{'Torgand-Saft':2,'Karpfen-Schuppenhaut':0,'Mondminze':0,'Batterie':0,'Filter':0,'UV-Spektral-Modul':0,'Karpfen-Essenz':0,'Schatzkarten-Fragment':0,'Wanderfisch':0,'Silberkarpfen':0},enchantments:[],logs:[],minute:42,moonlight:false,bonusCatches:0,recipe:null,revealed:0,props:null,listings:[{name:'Mondminze',qty:2,price:18,emoji:'🌿'},{name:'Schatzkarten-Fragment',qty:1,price:42,emoji:'🗺️'},{name:'Karpfen-Schuppenhaut',qty:1,price:35,emoji:'🐟'}]};
const el=id=>document.getElementById(id),itemEmoji={'Torgand-Saft':'🧪','Karpfen-Schuppenhaut':'🐟','Mondminze':'🌿','Batterie':'🔋','Filter':'◈','UV-Spektral-Modul':'☼','Karpfen-Essenz':'✨','Schatzkarten-Fragment':'🗺️','Wanderfisch':'🐠','Silberkarpfen':'🐟','Treibholz':'🪵','Schattenpilz':'🍄'};
function terrain(x,y){return map[y]?.[x]||'g'}function isWater(x,y){return terrain(x,y)==='w'}
function drawMap(){const world=el('world');world.innerHTML='';for(let y=0;y<H;y++)for(let x=0;x<W;x++){const t=terrain(x,y),tile=document.createElement('div');tile.className='tile '+({g:'grass',w:'water',p:'path',t:'tree',b:'building'}[t]||'grass');tile.dataset.x=x;tile.dataset.y=y;const prop=props[`${x},${y}`];if(prop?.emoji)tile.innerHTML=`<span>${prop.emoji}</span>`;else if(t==='t')tile.innerHTML='<span>🌲</span>';else if(t==='b')tile.innerHTML='<span>🏠</span>';if(x===state.x&&y===state.y){tile.classList.add('player');tile.innerHTML='<div class="player-token">🧢</div>'}world.append(tile)}el('coords').textContent=`X ${String(state.x).padStart(2,'0')} · Y ${String(state.y).padStart(2,'0')}`;updatePlace()}
function nearWater(){return [[-1,0],[1,0],[0,-1],[0,1]].some(([dx,dy])=>isWater(state.x+dx,state.y+dy))}
function updatePlace(){const p=props[`${state.x},${state.y}`];el('placeName').textContent=nearWater()?'Silberufer':p?.type==='guild'?'Gildensteg':'Mondhain';el('placeDesc').textContent=nearWater()?'Ein stiller See, voller Geheimnisse.':p?.type==='guild'?'Händler, Forschung und Geschichten.':'Wildkräuter wachsen zwischen den alten Pfaden.'}
