function makeEncounter(){const species=pokemonSpecies[Math.floor(Math.random()*pokemonSpecies.length)],level=2+Math.floor(Math.random()*4),ivs={},evs={hp:0,atk:0,def:0,spa:0,spd:0,spe:0},nature=natures[Math.floor(Math.random()*natures.length)];for(const key of Object.keys(statNames))ivs[key]=Math.floor(Math.random()*32);const pokemon={id:state.nextPokemonId++,species:species.name,emoji:species.emoji,level,nature:nature.name,ivs,evs,base:species.base,yield:species.yield,rarity:species.rarity};pokemon.stats=calcStats(pokemon);pokemon.maxHp=pokemon.stats.hp;pokemon.hp=pokemon.maxHp;return pokemon}
function calcStats(p){const nature=natures.find(n=>n.name===p.nature)||natures[0],stats={};for(const key of Object.keys(statNames)){const base=p.base[key],iv=p.ivs[key]||0,ev=p.evs[key]||0,core=Math.floor(((2*base+iv+Math.floor(ev/4))*p.level)/100);stats[key]=key==='hp'?core+p.level+10:Math.floor((core+5)*(nature.up===key?1.1:nature.down===key?.9:1))}return stats}
function ivTotal(p){return Object.values(p.ivs||{}).reduce((a,b)=>a+b,0)}function evTotal(p){return Object.values(p.evs||{}).reduce((a,b)=>a+b,0)}
function encounterChance(p){return Math.max(.12,Math.min(.92,(.24+.62*(1-p.hp/p.maxHp))/p.rarity))}
function encounterModal(){const p=state.activeEncounter;if(!p)return;const chance=Math.round(encounterChance(p)*100),hpPct=Math.max(0,p.hp/p.maxHp*100),ivLine=Object.keys(statNames).map(k=>`${statNames[k]} ${p.ivs[k]}`).join(' · '),evLine=Object.keys(statNames).filter(k=>p.evs[k]).map(k=>`${statNames[k]} +${p.evs[k]}`).join(' · ')||'Noch keine EVs';showModal(`${p.emoji} Wildes ${p.species}!`,`<p>Ein wildes <b>${p.species}</b> (Level ${p.level}) taucht im hohen Gras auf.</p><div class="hp-track"><i style="width:${hpPct}%"></i></div><p>KP ${p.hp} / ${p.maxHp} · Fangchance <b>${chance}%</b></p><div class="encounter-stats"><span>Wesen: ${p.nature}</span><span>IV-Summe: ${ivTotal(p)} / 186</span></div><p><b>IVs</b><br>${ivLine}</p><p><b>EVs</b><br>${evLine}</p><p>Schwäche es, um den Fang zu erleichtern. Besiegte Pokémon geben EVs an dein erstes Team-Pokémon.</p>`,[{label:`Pokéball werfen · ${chance}%`,run:catchEncounter},{label:'Angreifen',secondary:true,run:attackEncounter},{label:'Fliehen',secondary:true,run:()=>{state.activeEncounter=null;closeModal();log('Du bist der Begegnung im hohen Gras ausgewichen.');save()}}]);if(!state.inventory['Pokéball'])el('modalActions').firstChild.disabled=true}
function startEncounter(){const p=makeEncounter();state.activeEncounter=p;log(`Im hohen Gras erscheint ein wildes <strong>${p.species}</strong> (Level ${p.level})!`,true);encounterModal();save()}
function catchEncounter(){const p=state.activeEncounter;if(!p||!consume('Pokéball')){toast('Du hast keine Pokébälle mehr.');return}if(Math.random()<encounterChance(p)){state.pokemon.push({...p,hp:p.maxHp});state.activeEncounter=null;closeModal();renderPokemon();log(`<strong>${p.species}</strong> wurde gefangen! IV ${ivTotal(p)}/186, Wesen ${p.nature}.`,true);toast(`${p.emoji} ${p.species} gefangen!`);save()}else{toast('Der Pokémon entkommt dem Pokéball!');log(`${p.species} befreit sich aus dem Pokéball.`);encounterModal();save()}}
function attackEncounter(){const p=state.activeEncounter;if(!p)return;p.hp=Math.max(0,p.hp-(8+Math.floor(Math.random()*11)));if(p.hp===0){const lead=state.pokemon[0];if(lead){for(const [key,yieldAmount] of Object.entries(p.yield)){const total=evTotal(lead);if(total<510&&lead.evs[key]<252)lead.evs[key]+=Math.min(yieldAmount,510-total,252-lead.evs[key])}lead.stats=calcStats(lead);log(`${p.species} besiegt. <strong>${lead.species}</strong> erhält EVs: ${Object.entries(p.yield).map(([k,v])=>`${statNames[k]} +${v}`).join(', ')}.`);renderPokemon()}else log(`${p.species} flieht nach dem Kampf. Fang zuerst ein Pokémon, damit es EVs sammeln kann.`);state.activeEncounter=null;closeModal();toast(lead?'Kampf gewonnen — EVs erhalten.':'Das wilde Pokémon ist besiegt.')}else encounterModal();save()}
